/* Click the Pair offline support. Generated by tools/build.py.
   Network first: players always get the latest version while online, and the
   saved copy is only used when the network fails. Ads and analytics are never cached. */
const CACHE = 'click-the-pair-a0c7067a27';
const PRECACHE = [
  "/",
  "/hard.html",
  "/easy.html",
  "/animals.html",
  "/food.html",
  "/sports.html",
  "/new-years.html",
  "/valentines-day.html",
  "/st-patricks-day.html",
  "/easter.html",
  "/fourth-of-july.html",
  "/halloween.html",
  "/thanksgiving.html",
  "/christmas.html",
  "/assets/game.js?v=20c2ac5c7c",
  "/manifest.webmanifest",
  "/favicon.ico",
  "/icons/icon-192.png",
  "/icons/apple-touch-icon.png"
];

self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(key => key !== CACHE).map(key => caches.delete(key))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  const isPage = request.mode === 'navigate';
  const key = isPage ? url.origin + url.pathname : request;
  event.respondWith(
    fetch(request)
      .then(response => {
        if (response.ok && response.type === 'basic') {
          const copy = response.clone();
          caches.open(CACHE).then(cache => cache.put(key, copy));
        }
        return response;
      })
      .catch(() => caches.match(key).then(hit => hit || (isPage ? caches.match('/') : Response.error())))
  );
});
